"use client";

import { useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useAuth } from "@/contexts/AuthContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import {
  ArrowRight,
  LockKeyhole,
  Loader2,
  Mail,
  UserRound,
  Flame,
  Dumbbell,
  HeartPulse,
  ShieldCheck,
  Sparkles,
  Star,
  CheckCircle2,
} from "lucide-react";

const PLANS = [
  { icon: Dumbbell,    title: "Full Gym Access",   desc: "Every machine, every rack — yours." },
  { icon: HeartPulse,  title: "Fitness Tracking",  desc: "Log workouts and monitor progress." },
  { icon: ShieldCheck, title: "Expert Guidance",   desc: "Certified trainers on the floor daily." },
  { icon: Sparkles,    title: "Nutrition Support", desc: "Meal plans tailored to your goals." },
];

const REVIEWS = [
  { name: "Aisha R.", avatar: "A", text: "I went from couch to 5K in 8 weeks. The community kept me going.", rating: 5 },
  { name: "James L.", avatar: "J", text: "Best investment I've made. The coaches genuinely care about results.", rating: 5 },
  { name: "Priya M.", avatar: "P", text: "Clean facility, great classes, amazing vibe. Wouldn't go anywhere else.", rating: 5 },
];

function Field({
  id, label, type = "text", placeholder, value, onChange, icon: Icon, disabled,
}: {
  id: string; label: string; type?: string; placeholder: string;
  value: string; onChange: (v: string) => void; icon: typeof UserRound; disabled: boolean;
}) {
  return (
    <div className="space-y-1.5">
      <Label htmlFor={id} className="text-zinc-700 font-medium text-sm">{label}</Label>
      <div className="relative">
        <Icon className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-zinc-400" />
        <Input
          id={id} type={type} placeholder={placeholder} value={value}
          onChange={(e) => onChange(e.target.value)} required disabled={disabled}
          minLength={type === "password" ? 6 : undefined}
          className="h-11 rounded-xl border-zinc-200 bg-zinc-50 pl-10 text-zinc-900 placeholder:text-zinc-400 focus-visible:ring-red-500 focus-visible:border-red-400 transition-colors"
        />
      </div>
    </div>
  );
}

export default function RegisterPage() {
  const router = useRouter();
  const { register } = useAuth();
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [reviewIdx, setReviewIdx] = useState(0);

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setIsLoading(true);
    try {
      if (password !== confirmPassword) throw new Error("Passwords do not match");
      if (password.length < 6) throw new Error("Password must be at least 6 characters");
      await register(email, password, name);
      toast.success("Welcome to Forge Gym! Let's get to work.");
      router.push("/");
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Registration failed");
    } finally {
      setIsLoading(false);
    }
  };

  const r = REVIEWS[reviewIdx];

  return (
    <div className="h-screen w-screen overflow-hidden grid lg:grid-cols-[1fr_480px] xl:grid-cols-[1fr_540px]">

      {/* ═══════════════ LEFT — Full-bleed Photo Panel ═══════════════ */}
      <aside
        className="hidden lg:flex flex-col relative"
        style={{
          backgroundImage: "url('/auth-gym-hero.png')",
          backgroundSize: "cover",
          backgroundPosition: "center",
        }}
      >
        {/* Gradient overlays */}
        <div className="absolute inset-0 bg-gradient-to-b from-black/80 via-black/25 to-black/85" />
        <div className="absolute inset-x-0 bottom-0 h-2/5 bg-gradient-to-t from-red-950/55 to-transparent" />

        <div className="relative z-10 flex flex-col h-full p-10 xl:p-14">

          {/* Logo */}
          <Link href="/" className="inline-flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-red-500 to-orange-500 shadow-lg shadow-red-700/50">
              <Flame className="h-5 w-5 text-white" />
            </div>
            <span className="text-lg font-bold tracking-widest text-white uppercase">Forge Gym</span>
          </Link>

          {/* Headline */}
          <div className="flex-1 flex flex-col justify-center">
            <p className="text-[11px] font-bold uppercase tracking-[.38em] text-red-400 mb-5">
              Free membership — no commitment
            </p>
            <h1 className="text-5xl xl:text-6xl font-extrabold leading-[1.05] text-white drop-shadow-lg">
              The Only Gym<br />
              That{" "}
              <span className="bg-gradient-to-r from-red-400 to-orange-300 bg-clip-text text-transparent">
                Grows
              </span>
              <br />
              With You.
            </h1>
            <p className="mt-5 text-sm text-zinc-300 leading-relaxed max-w-sm">
              Everything you need to build the body and mindset you&apos;ve always wanted — under one roof.
            </p>

            {/* Feature cards */}
            <div className="mt-8 grid grid-cols-2 gap-3">
              {PLANS.map(({ icon: Icon, title, desc }) => (
                <div
                  key={title}
                  className="rounded-2xl bg-black/40 border border-white/10 p-4 backdrop-blur-md"
                >
                  <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-red-500/20 mb-2.5">
                    <Icon className="h-4 w-4 text-red-400" />
                  </div>
                  <p className="text-xs font-bold text-white mb-0.5">{title}</p>
                  <p className="text-[11px] text-zinc-400 leading-relaxed">{desc}</p>
                </div>
              ))}
            </div>
          </div>

          {/* Social proof */}
          <div className="flex items-center gap-3 mb-5">
            <div className="flex -space-x-2">
              {["bg-red-500","bg-orange-500","bg-amber-500","bg-rose-500"].map((color, i) => (
                <div
                  key={i}
                  className={`h-8 w-8 rounded-full border-2 border-black/60 ${color} flex items-center justify-center text-white text-[10px] font-bold`}
                >
                  {["S","M","A","J"][i]}
                </div>
              ))}
            </div>
            <div>
              <div className="flex gap-0.5 mb-0.5">
                {Array.from({ length: 5 }).map((_, i) => (
                  <Star key={i} className="h-3 w-3 fill-yellow-400 text-yellow-400" />
                ))}
              </div>
              <p className="text-[11px] text-zinc-400">
                Joined by <span className="text-white font-semibold">12,000+</span> members
              </p>
            </div>
          </div>

          {/* Testimonial */}
          <div className="rounded-2xl border border-white/10 bg-black/40 backdrop-blur-md p-5">
            <div className="flex items-start gap-3 mb-3">
              <div className="flex h-9 w-9 items-center justify-center rounded-full bg-gradient-to-br from-red-500 to-orange-500 text-white text-sm font-bold shrink-0">
                {r.avatar}
              </div>
              <div>
                <p className="text-xs font-semibold text-white">{r.name}</p>
                <div className="flex gap-0.5 mt-0.5">
                  {Array.from({ length: r.rating }).map((_, i) => (
                    <Star key={i} className="h-3 w-3 fill-yellow-400 text-yellow-400" />
                  ))}
                </div>
              </div>
            </div>
            <p className="text-sm text-zinc-200 leading-relaxed mb-3">&ldquo;{r.text}&rdquo;</p>
            <div className="flex justify-end gap-1.5">
              {REVIEWS.map((_, i) => (
                <button
                  key={i}
                  onClick={() => setReviewIdx(i)}
                  className={`h-1.5 rounded-full transition-all ${
                    i === reviewIdx ? "w-5 bg-red-400" : "w-1.5 bg-white/25"
                  }`}
                />
              ))}
            </div>
          </div>

        </div>
      </aside>

      {/* ═══════════════ RIGHT — Form Panel ═══════════════ */}
      <section className="flex flex-col items-center justify-center bg-white overflow-y-auto px-8 py-10 sm:px-12">
        <div className="w-full max-w-[360px]">

          {/* Mobile logo */}
          <Link href="/" className="mb-8 inline-flex items-center gap-2.5 lg:hidden">
            <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-gradient-to-br from-red-500 to-orange-500 shadow-md shadow-red-500/30">
              <Flame className="h-4 w-4 text-white" />
            </div>
            <span className="text-sm font-bold uppercase tracking-widest text-zinc-800">Forge Gym</span>
          </Link>

          {/* Heading */}
          <header className="mb-7">
            <p className="mb-2 text-[11px] font-bold uppercase tracking-[.38em] text-red-500">
              Join the movement
            </p>
            <h2 className="text-[1.75rem] font-extrabold tracking-tight text-zinc-900 leading-tight">
              Create your account
            </h2>
            <p className="mt-2 text-sm text-zinc-500">Free to join. No credit card required.</p>
          </header>

          {/* Quick perks */}
          <ul className="mb-6 space-y-1.5">
            {["Instant access to all features","Personalised fitness dashboard","Track classes & equipment"].map((item) => (
              <li key={item} className="flex items-center gap-2 text-xs text-zinc-500">
                <CheckCircle2 className="h-3.5 w-3.5 text-red-400 shrink-0" />
                {item}
              </li>
            ))}
          </ul>

          {/* Form */}
          <form onSubmit={handleSubmit} className="space-y-4">
            <Field id="name" label="Full name" placeholder="John Doe" value={name} onChange={setName} icon={UserRound} disabled={isLoading} />
            <Field id="email" label="Email address" type="email" placeholder="you@example.com" value={email} onChange={setEmail} icon={Mail} disabled={isLoading} />

            <div className="grid grid-cols-2 gap-3">
              <Field id="password" label="Password" type="password" placeholder="Min. 6 chars" value={password} onChange={setPassword} icon={LockKeyhole} disabled={isLoading} />
              <Field id="confirmPassword" label="Confirm" type="password" placeholder="Repeat" value={confirmPassword} onChange={setConfirmPassword} icon={LockKeyhole} disabled={isLoading} />
            </div>

            <p className="text-[11px] text-zinc-400 leading-relaxed">
              By creating an account you agree to our{" "}
              <button type="button" className="text-red-500 hover:underline font-medium">Terms of Service</button>
              {" "}and{" "}
              <button type="button" className="text-red-500 hover:underline font-medium">Privacy Policy</button>.
            </p>

            <Button
              type="submit"
              disabled={isLoading}
              className="h-11 w-full rounded-xl bg-gradient-to-r from-red-600 to-orange-500 text-sm font-bold text-white shadow-md shadow-red-500/25 hover:from-red-700 hover:to-orange-600 transition-all"
            >
              {isLoading ? (
                <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Creating account...</>
              ) : (
                <>Create free account <ArrowRight className="ml-2 h-4 w-4" /></>
              )}
            </Button>
          </form>

          <p className="mt-7 text-center text-sm text-zinc-500">
            Already a member?{" "}
            <Link href="/login" className="font-semibold text-red-500 hover:text-red-600 underline-offset-2 hover:underline transition-colors">
              Sign in
            </Link>
          </p>

        </div>
      </section>

    </div>
  );
}
